import type { Question, StudyModule } from "../module-types";

// ---------- MOM-01: Stress and Strain ----------

const lessonsStressStrain=[
{title:"Normal and shear stress",body:"Normal stress σ=P/A acts perpendicular to a cross-section under axial load; shear stress τ=V/A acts parallel to the surface, as in a bolt or pin connection. Always determine the actual area resisting the load — for shear connections, check whether the fastener is in single or double shear before dividing."},
{title:"Hooke's law and the stress-strain diagram",body:"Below the proportional limit, stress and strain are linearly related by σ=Eε, where E is the modulus of elasticity (the slope of the initial straight-line portion of the curve). Beyond the proportional limit the material yields; for metals without a sharp yield point, the 0.2% offset method defines a practical yield strength."},
{title:"Poisson's ratio",body:"When a bar stretches axially, it contracts laterally (and vice versa in compression). Poisson's ratio ν=−ε_lateral/ε_axial quantifies this effect and typically ranges from about 0.25 to 0.35 for metals. It is always positive for ordinary engineering materials."},
{title:"Factor of safety and allowable stress",body:"Design stresses are kept below the material's yield (or ultimate) strength by a factor of safety: σ_allow=σ_yield/FS. Compute the allowable stress first, then size the member (A=P/σ_allow) or check the load capacity (P_allow=σ_allow×A) — never apply the full yield strength directly."}
];

const flashcardsStressStrain=[
{front:"Normal stress",back:"σ=P/A",note:"P is the axial force normal to the cross-section; A is the area it acts over."},
{front:"Shear stress (average)",back:"τ=V/A",note:"Check whether the connection is in single or double shear before choosing A."},
{front:"Hooke's law (axial)",back:"σ=Eε",note:"Valid only below the proportional limit."},
{front:"Poisson's ratio",back:"ν=−ε_lateral/ε_axial",note:"Lateral strain is opposite in sign to axial strain for a stretched bar."},
{front:"Modulus of elasticity",back:"E=σ/ε (slope of the stress-strain curve)",note:"Steel ≈200 GPa; aluminum ≈69 GPa — don't mix them up."},
{front:"Shear modulus",back:"G=τ/γ",note:"γ is the engineering shear strain (angle change in radians)."},
{front:"Factor of safety",back:"FS=σ_yield/σ_allow",note:"Apply FS to the strength before computing allowable load, not after."},
{front:"Allowable load",back:"P_allow=σ_allow×A",note:"Never use σ_yield directly as the design stress — always apply the FS first."}
];

const questionsStressStrain:Question[]=[
{id:"MOM01-Q01",skill:"Normal stress",difficulty:"Easy",prompt:"A circular rod, 20 mm in diameter, carries an axial tensile load of 50 kN. Find the normal stress in the rod.",choices:["39.8 MPa","125.0 MPa","159.2 MPa","318.3 MPa"],answer:2,explanation:"The normal stress is about 159.2 MPa.",solution:"Step 1 — Compute the cross-sectional area: A=(π/4)d²=(π/4)(20)².\nStep 2 — A=(π/4)(400)=314.16 mm².\nStep 3 — σ=P/A=50,000 N/314.16 mm².\nFinal answer: 159.2 MPa.",trap:"125.0 MPa comes from using A=d²=400 mm² (treating the cross-section as a square) instead of the correct circular area A=(π/4)d²=314.16 mm².",repair:"For a circular cross-section, always use A=(π/4)d², not d² — the π/4 factor is not optional."},
{id:"MOM01-Q02",skill:"Shear stress",difficulty:"Easy",prompt:"A bolt in single shear, 12 mm in diameter, carries a shear load of 8 kN. Find the average shear stress in the bolt.",choices:["17.7 MPa","35.4 MPa","70.7 MPa","141.5 MPa"],answer:2,explanation:"The average shear stress is about 70.7 MPa.",solution:"Step 1 — Compute the shear area: A=(π/4)(12)²=113.10 mm².\nStep 2 — For single shear, τ=V/A (one shear plane).\nStep 3 — τ=8,000 N/113.10 mm².\nFinal answer: 70.7 MPa.",trap:"141.5 MPa comes from doubling the single-shear result (τ=2V/A), as if the load needed to be split across two shear planes when the bolt is only in single shear.",repair:"Count the actual shear planes from the joint sketch before choosing the formula — single shear uses τ=V/A, double shear uses τ=V/(2A)."},
{id:"MOM01-Q03",skill:"Hooke's law",difficulty:"Easy",prompt:"A steel rod (E=200 GPa) is loaded in tension to a stress of 150 MPa, staying within the elastic range. What is the resulting normal strain?",choices:["7.5 × 10⁻⁴","1.5 × 10⁻³","7.5 × 10⁻³","7.5 × 10⁻¹"],answer:0,explanation:"The strain is about 7.5×10⁻⁴ (750 microstrain).",solution:"Step 1 — Hooke's law: σ=Eε, so ε=σ/E.\nStep 2 — Convert E to consistent units: E=200 GPa=200,000 MPa.\nStep 3 — ε=150 MPa/200,000 MPa.\nFinal answer: 7.5×10⁻⁴ (750 µε).",trap:"7.5×10⁻¹ results from forgetting to convert E from GPa to MPa (using E=200 instead of 200,000), inflating the computed strain by a factor of 1000.",repair:"Always convert E and σ to the same stress units (both MPa or both GPa) before dividing to find strain."},
{id:"MOM01-Q04",skill:"Poisson's ratio",difficulty:"Medium",prompt:"A tension test specimen shows an axial strain of 0.0012 and a lateral strain of −0.00036. Find Poisson's ratio for the material.",choices:["0.12","0.20","0.30","0.36"],answer:2,explanation:"Poisson's ratio is 0.30.",solution:"Step 1 — Poisson's ratio: ν=−ε_lateral/ε_axial.\nStep 2 — Substitute magnitudes: ν=0.00036/0.0012.\nStep 3 — Divide: 0.00036/0.0012=0.30.\nFinal answer: 0.30.",trap:"0.36 comes from a decimal-place slip when dividing 0.00036 by 0.0012 (misreading it as 36/100 instead of 36/120), overstating the ratio.",repair:"Convert both strains to the same units (e.g. microstrain) before dividing, so decimal places line up cleanly: 360/1200=0.30."},
{id:"MOM01-Q05",skill:"Shear stress, double shear",difficulty:"Medium",prompt:"Two plates are joined by a pin in double shear. The pin is 16 mm in diameter and the connection carries a total load of 40 kN. Find the average shear stress in the pin.",choices:["49.7 MPa","99.5 MPa","198.9 MPa","397.9 MPa"],answer:1,explanation:"The average shear stress is about 99.5 MPa.",solution:"Step 1 — Compute the pin area: A=(π/4)(16)²=201.06 mm².\nStep 2 — The pin is in double shear, so it resists the load across two planes: τ=P/(2A).\nStep 3 — τ=40,000 N/(2×201.06 mm²)=40,000/402.12.\nFinal answer: 99.5 MPa.",trap:"198.9 MPa results from using the single-shear formula τ=P/A and ignoring that the pin has two shear planes carrying the load.",repair:"Identify the number of shear planes from the connection sketch — a double-shear pin splits the load across two areas: τ=P/(2A)."},
{id:"MOM01-Q06",skill:"Factor of safety",difficulty:"Medium",prompt:"A tie rod is made from steel with a yield strength of 250 MPa. Using a factor of safety of 2.5 based on yield, and a cross-sectional area of 500 mm², what is the maximum allowable axial load?",choices:["20.0 kN","50.0 kN","62.5 kN","125.0 kN"],answer:1,explanation:"The maximum allowable load is 50.0 kN.",solution:"Step 1 — Find the allowable stress: σ_allow=σ_yield/FS=250/2.5.\nStep 2 — σ_allow=100 MPa.\nStep 3 — P_allow=σ_allow×A=100 MPa×500 mm².\nFinal answer: 50.0 kN.",trap:"125.0 kN comes from applying the full yield stress (250 MPa) directly to the area, skipping the factor of safety entirely.",repair:"Always divide the yield (or ultimate) strength by the factor of safety to get the allowable stress before computing the allowable load."},
{id:"MOM01-Q07",skill:"Modulus of elasticity from test data",difficulty:"Hard",prompt:"A tensile coupon with a 10 mm diameter is loaded axially to 15 kN, remaining within the elastic region. The measured elongation over a 100 mm gauge length is 0.15 mm. Determine the modulus of elasticity E.",choices:["100.0 GPa","127.3 GPa","150.0 GPa","254.6 GPa"],answer:1,explanation:"The modulus of elasticity is about 127.3 GPa.",solution:"Step 1 — Area: A=(π/4)(10)²=78.54 mm².\nStep 2 — Stress: σ=P/A=15,000 N/78.54 mm²=191.0 MPa.\nStep 3 — Strain: ε=δ/L=0.15 mm/100 mm=0.0015.\nStep 4 — E=σ/ε=191.0 MPa/0.0015.\nFinal answer: 127.3 GPa.",trap:"100.0 GPa results from computing the area as A=d²=100 mm² (a square cross-section) instead of the correct circular area (π/4)d²=78.54 mm², which understates the stress and therefore E.",repair:"For a circular specimen, always compute area as A=(π/4)d² — never substitute d² directly."},
{id:"MOM01-Q08",skill:"Shear modulus",difficulty:"Hard",prompt:"A material specimen subjected to a shear stress of 45 MPa exhibits a shear strain of 0.0006 rad. Find the shear modulus G.",choices:["7.5 GPa","37.5 GPa","75.0 GPa","150.0 GPa"],answer:2,explanation:"The shear modulus is 75.0 GPa.",solution:"Step 1 — G=τ/γ.\nStep 2 — Substitute: G=45 MPa/0.0006.\nStep 3 — 45/0.0006=75,000 MPa.\nFinal answer: 75.0 GPa.",trap:"37.5 GPa results from dividing by (2×γ) instead of γ, confusing the engineering shear strain with the tensor shear-strain convention (which carries an extra factor of 2).",repair:"Use the engineering shear strain γ (the total angular distortion) directly in G=τ/γ — do not insert an extra factor of 2."},
{id:"MOM01-Q09",skill:"Sizing for allowable stress",difficulty:"Medium",prompt:"A steel tie rod must carry an axial tensile load of 90 kN without exceeding an allowable stress of 140 MPa. What is the minimum required rod diameter?",choices:["14.3 mm","20.2 mm","28.6 mm","40.5 mm"],answer:2,explanation:"The minimum required diameter is about 28.6 mm.",solution:"Step 1 — Required area: A=P/σ_allow=90,000 N/140 MPa=642.9 mm².\nStep 2 — Solve for diameter from A=(π/4)d²: d=√(4A/π).\nStep 3 — d=√(4×642.9/π)=√818.5.\nFinal answer: 28.6 mm.",trap:"14.3 mm comes from solving d=√(A/π), which is equivalent to using A=πd² instead of the correct A=(π/4)d² — omitting the factor of 4 under the square root.",repair:"When solving backward for diameter, always invert the correct area formula A=(π/4)d² to get d=√(4A/π), not d=√(A/π)."},
{id:"MOM01-Q10",skill:"Stress-strain diagram concepts",difficulty:"Medium",prompt:"On a typical engineering stress-strain diagram for a ductile steel with no sharp yield point, the stress found by drawing a line parallel to the elastic slope, offset by a strain of 0.002, and reading where it intersects the curve is called the:",choices:["Proportional limit","Yield strength (0.2% offset)","Ultimate tensile strength","Fracture strength"],answer:1,explanation:"This construction defines the 0.2% offset yield strength.",solution:"Step 1 — The proportional limit is where the curve first departs from a straight line — no offset construction is needed to find it.\nStep 2 — Many ductile metals have no sharp yield point, so a line parallel to the initial elastic slope is drawn starting at 0.002 (0.2%) strain.\nStep 3 — Where this offset line intersects the stress-strain curve defines a practical yield strength for design purposes.\nFinal answer: Yield strength (0.2% offset).",trap:"Proportional limit is a tempting choice since it is also tied to the onset of nonlinearity, but it marks the end of purely linear-elastic behavior, not the 0.2%-offset construction used to define yield strength.",repair:"Reserve 'proportional limit' for the end of linearity, and 'yield strength' for the 0.2%-offset (or observed yield-point) definition of the onset of significant plastic strain."}
];

export const mechanicsStressStrainModule:StudyModule={id:"MOM-01",subjectId:"mechanics-materials",sectionId:"stress-strain",title:"Stress and Strain",lessons:lessonsStressStrain,flashcards:flashcardsStressStrain,questions:questionsStressStrain};

// ---------- MOM-02: Axial Loading and Torsion ----------

const lessonsAxialTorsion=[
{title:"Axial deformation",body:"Under axial load, a member elongates (or shortens) by δ=PL/AE. For a stepped member with segments of different P, A, or E, total deformation is the sum of each segment's own PL/AE — always find the internal (not just applied) force in each segment first."},
{title:"Torsional shear stress in circular shafts",body:"A torque T produces shear stress τ=Tr/J at radius r, maximum at the outer surface (r=c). For a solid circular shaft J=πd⁴/32; for a hollow shaft J=π(do⁴−di⁴)/32. J is the polar moment of inertia — do not confuse it with the bending moment of inertia I."},
{title:"Angle of twist",body:"A circular shaft twists by φ=TL/(JG), in radians, where G is the shear modulus. As with axial deformation, sum each segment's φ for a stepped or multi-loaded shaft, using the correct internal torque (from a torque diagram) in each segment."},
{title:"Power-torque-speed relation",body:"A rotating shaft transmitting power P at angular speed ω satisfies P=Tω. Convert rotational speed to rad/s first: ω=2πn/60 for n in rpm. Forgetting the 2π (revolutions to radians) or the 60 (minutes to seconds) is a common source of error."}
];

const flashcardsAxialTorsion=[
{front:"Axial deformation",back:"δ=PL/AE",note:"Sum PL/AE for each segment when P, A, or E changes along the length."},
{front:"Torsional shear stress",back:"τ=Tr/J (max at r=c, the outer surface)",note:"J=πd⁴/32 for a solid circular shaft."},
{front:"Angle of twist",back:"φ=TL/(JG) (radians)",note:"Convert to degrees by multiplying by 180/π."},
{front:"Polar moment of inertia (solid)",back:"J=πd⁴/32 = πc⁴/2",note:"c is the outer radius."},
{front:"Polar moment of inertia (hollow)",back:"J=π(do⁴−di⁴)/32",note:"Subtract the inner-diameter term — do not just use the outer diameter."},
{front:"Power-torque relation",back:"P=Tω",note:"ω must be in rad/s: ω=2πn/60 for n in rpm."},
{front:"Shear strain in torsion",back:"γ=rφ/L=τ/G",note:"Shear strain varies linearly with radius, zero at the center."},
{front:"Internal torque in a segment",back:"Sum all applied torques beyond (downstream of) the cut section",note:"Draw a torque diagram — don't assume a segment only carries its own local applied torque."}
];

const questionsAxialTorsion:Question[]=[
{id:"MOM02-Q01",skill:"Axial deformation",difficulty:"Easy",prompt:"A steel rod (E=200 GPa), 2 m long with a cross-sectional area of 300 mm², carries an axial tensile load of 60 kN. Find the elongation of the rod.",choices:["1.0 mm","2.0 mm","4.0 mm","6.0 mm"],answer:1,explanation:"The rod elongates by 2.0 mm.",solution:"Step 1 — δ=PL/AE.\nStep 2 — Convert units: P=60,000 N, L=2000 mm, A=300 mm², E=200,000 MPa.\nStep 3 — δ=(60,000×2000)/(300×200,000)=120,000,000/60,000,000.\nFinal answer: 2.0 mm.",trap:"4.0 mm results from using E=100 GPa (an aluminum-like value) instead of the correct 200 GPa for steel, halving the denominator.",repair:"Double-check the modulus of elasticity against the stated material — steel ≈200 GPa, aluminum ≈69 GPa."},
{id:"MOM02-Q02",skill:"Torsional shear stress",difficulty:"Easy",prompt:"A solid circular shaft, 40 mm in diameter, transmits a torque of 300 N·m. Find the maximum shear stress in the shaft.",choices:["11.9 MPa","23.9 MPa","47.7 MPa","95.5 MPa"],answer:1,explanation:"The maximum shear stress is about 23.9 MPa.",solution:"Step 1 — J=πd⁴/32=π(40)⁴/32=251,327 mm⁴.\nStep 2 — c=d/2=20 mm.\nStep 3 — τ=Tc/J=(300,000 N·mm)(20 mm)/251,327 mm⁴.\nFinal answer: 23.9 MPa.",trap:"47.7 MPa comes from using the full diameter (40 mm) as c instead of the outer radius (20 mm) in τ=Tc/J, doubling the computed stress.",repair:"c in τ=Tc/J is always a radius (half the diameter), never the full diameter."},
{id:"MOM02-Q03",skill:"Angle of twist",difficulty:"Medium",prompt:"A solid steel shaft (G=80 GPa), 1.5 m long and 30 mm in diameter, is subjected to a torque of 200 N·m. Find the angle of twist, in degrees.",choices:["1.35°","2.70°","5.40°","10.80°"],answer:1,explanation:"The angle of twist is about 2.70°.",solution:"Step 1 — J=πd⁴/32=π(30)⁴/32=79,522 mm⁴.\nStep 2 — φ(rad)=TL/(JG)=(200,000 N·mm)(1500 mm)/(79,522 mm⁴×80,000 MPa).\nStep 3 — φ=300,000,000/6,361,726,000=0.04716 rad.\nStep 4 — Convert to degrees: 0.04716×(180/π).\nFinal answer: 2.70°.",trap:"5.40° results from using G=40 GPa instead of steel's actual G≈80 GPa, which doubles the computed twist.",repair:"Confirm the shear modulus G for the actual material (steel G≈80 GPa) rather than assuming a generic value."},
{id:"MOM02-Q04",skill:"Stepped member deformation",difficulty:"Medium",prompt:"A stepped steel rod (E=200 GPa) has segment AB: 400 mm long, area 500 mm², and segment BC: 600 mm long, area 250 mm². Both segments carry the same axial tensile force of 40 kN. Find the total elongation of the rod.",choices:["0.32 mm","0.48 mm","0.64 mm","0.80 mm"],answer:2,explanation:"The total elongation is 0.64 mm.",solution:"Step 1 — δ_AB=PL/AE=(40,000×400)/(500×200,000)=0.16 mm.\nStep 2 — δ_BC=PL/AE=(40,000×600)/(250×200,000)=0.48 mm.\nStep 3 — Total elongation=δ_AB+δ_BC=0.16+0.48.\nFinal answer: 0.64 mm.",trap:"0.48 mm counts only segment BC's contribution and forgets to add segment AB's 0.16 mm.",repair:"For a stepped member, sum the PL/AE contribution of every segment — don't stop after the first (or largest) one."},
{id:"MOM02-Q05",skill:"Power-torque relation",difficulty:"Medium",prompt:"A shaft rotates at 1800 rpm and transmits 50 kW of power. Find the torque carried by the shaft.",choices:["132.6 N·m","265.3 N·m","530.5 N·m","1591.5 N·m"],answer:1,explanation:"The torque is about 265.3 N·m.",solution:"Step 1 — Convert speed to rad/s: ω=2πn/60=2π(1800)/60.\nStep 2 — ω=188.5 rad/s.\nStep 3 — T=P/ω=50,000 W/188.5 rad/s.\nFinal answer: 265.3 N·m.",trap:"530.5 N·m comes from using ω=πn/60 instead of ω=2πn/60 — dropping the factor of 2 that converts revolutions to radians.",repair:"Anchor angle conversions to one revolution = 2π radians: ω(rad/s)=2πn(rpm)/60."},
{id:"MOM02-Q06",skill:"Hollow shaft torsion",difficulty:"Medium",prompt:"A hollow steel shaft has an outer diameter of 60 mm and an inner diameter of 40 mm, and transmits a torque of 1200 N·m. Find the maximum shear stress in the shaft.",choices:["17.6 MPa","35.3 MPa","44.1 MPa","70.5 MPa"],answer:1,explanation:"The maximum shear stress is about 35.3 MPa.",solution:"Step 1 — J=π(do⁴−di⁴)/32=π(60⁴−40⁴)/32=π(12,960,000−2,560,000)/32.\nStep 2 — J=π(10,400,000)/32=1,021,018 mm⁴.\nStep 3 — c=outer radius=30 mm.\nStep 4 — τ=Tc/J=(1,200,000 N·mm)(30 mm)/1,021,018 mm⁴.\nFinal answer: 35.3 MPa.",trap:"70.5 MPa comes from using the full outer diameter (60 mm) as c instead of the outer radius (30 mm) in τ=Tc/J.",repair:"c in τ=Tc/J is always a radius, even for a hollow shaft — use the outer radius for the maximum stress."},
{id:"MOM02-Q07",skill:"Shaft design for allowable stress",difficulty:"Hard",prompt:"A solid circular shaft must transmit a torque of 500 N·m without exceeding an allowable shear stress of 60 MPa. What is the minimum required shaft diameter?",choices:["27.7 mm","34.9 mm","43.9 mm","55.3 mm"],answer:1,explanation:"The minimum required diameter is about 34.9 mm.",solution:"Step 1 — Rearranging τ=Tc/J with J=πd⁴/32 and c=d/2 gives d³=16T/(πτ_allow).\nStep 2 — d³=16(500,000 N·mm)/(π×60 MPa)=8,000,000/188.5.\nStep 3 — d³=42,441 mm³.\nStep 4 — d=∛42,441.\nFinal answer: 34.9 mm.",trap:"43.9 mm results from confusing the polar moment of inertia J=πd⁴/32 with the bending moment of inertia I=πd⁴/64 (using d³=32T/(πτ) instead of 16T/(πτ)), which roughly doubles the computed diameter requirement.",repair:"For torsion of circular shafts, always use the polar moment J=πd⁴/32 (not the bending moment of inertia I=πd⁴/64)."},
{id:"MOM02-Q08",skill:"Multi-segment torque diagram",difficulty:"Hard",prompt:"A shaft is fixed at A. Gear B applies 150 N·m and gear C, at the free end, applies an additional 100 N·m, both in the same rotational sense. Segment AB is 0.8 m long and segment BC is 0.6 m long; the shaft has a uniform 25 mm diameter and G=80 GPa. Find the total angle of twist at C relative to A.",choices:["2.61°","3.73°","4.86°","7.29°"],answer:2,explanation:"The total angle of twist is about 4.86°.",solution:"Step 1 — Internal torque in AB must carry both downstream gears: T_AB=150+100=250 N·m. Internal torque in BC carries only gear C: T_BC=100 N·m.\nStep 2 — J=πd⁴/32=π(25)⁴/32=38,350 mm⁴.\nStep 3 — φ_AB=T_AB·L_AB/(JG)=(250,000×800)/(38,350×80,000)=0.0652 rad.\nStep 4 — φ_BC=T_BC·L_BC/(JG)=(100,000×600)/(38,350×80,000)=0.0196 rad.\nStep 5 — Total φ=0.0652+0.0196=0.0847 rad, converted to degrees: 0.0847×(180/π).\nFinal answer: 4.86°.",trap:"2.61° comes from using only the locally applied torque (100 N·m) in segment AB, instead of recognizing that AB must transmit the full 250 N·m from both downstream gears.",repair:"Draw an internal torque diagram: the internal torque in each segment equals the sum of all applied torques beyond that section, not just the nearest one."},
{id:"MOM02-Q09",skill:"Axial deformation concepts",difficulty:"Easy",prompt:"Which of the following, acting alone, will increase the axial elongation of a rod under a fixed tensile load P (all else equal)?",choices:["Increasing the cross-sectional area A","Increasing the modulus of elasticity E","Increasing the length L","Decreasing the applied load P"],answer:2,explanation:"Elongation δ=PL/AE increases directly with L.",solution:"Step 1 — δ=PL/AE.\nStep 2 — δ is directly proportional to L (numerator), and inversely proportional to A and E (denominator).\nStep 3 — Increasing A or E decreases δ; decreasing P decreases δ; increasing L increases δ.\nFinal answer: Increasing the length L.",trap:"Increasing A is a tempting choice since it also appears in the formula, but A is in the denominator — increasing A decreases δ, it does not increase it.",repair:"Check whether each variable is in the numerator (direct relationship) or denominator (inverse relationship) of δ=PL/AE before predicting the effect of a change."},
{id:"MOM02-Q10",skill:"Torsional stiffness",difficulty:"Medium",prompt:"A solid circular shaft, 25 mm in diameter and 1.2 m long, has G=77 GPa. What torque is required to produce a twist of 3° between its ends?",choices:["64.4 N·m","128.8 N·m","193.2 N·m","257.7 N·m"],answer:1,explanation:"The required torque is about 128.8 N·m.",solution:"Step 1 — Convert the angle to radians: φ=3°×(π/180)=0.05236 rad.\nStep 2 — J=πd⁴/32=π(25)⁴/32=38,350 mm⁴.\nStep 3 — T=φJG/L=(0.05236×38,350×77,000)/1200.\nFinal answer: 128.8 N·m.",trap:"64.4 N·m comes from converting degrees to radians using 360°=π rad (an extra factor of 2) instead of the correct 180°=π rad, halving the twist angle and thus the torque.",repair:"Anchor angle conversions to 180°=π rad — check by testing a known value like 90°=π/2 rad."}
];

export const mechanicsAxialTorsionModule:StudyModule={id:"MOM-02",subjectId:"mechanics-materials",sectionId:"axial-torsion",title:"Axial Loading and Torsion",lessons:lessonsAxialTorsion,flashcards:flashcardsAxialTorsion,questions:questionsAxialTorsion};

// ---------- MOM-03: Beams: Shear, Moment, and Deflection ----------

const lessonsBeams=[
{title:"Shear and moment relationships",body:"The load, shear, and moment diagrams are linked by dV/dx=−w(x) and dM/dx=V(x). A point load causes a step (jump) in the shear diagram; a point moment causes a step in the moment diagram. Maximum bending moment occurs where the shear diagram crosses zero."},
{title:"Flexure formula",body:"The maximum bending (normal) stress at a section is σ=Mc/I, where c is the distance from the neutral axis to the extreme fiber and I is the area moment of inertia about the neutral axis. Tension and compression occur on opposite faces of the beam."},
{title:"Common section properties",body:"For a rectangle of width b and depth h, I=bh³/12 and c=h/2 (h measured in the direction of bending). For a solid circle of diameter d, I=πd⁴/64 and c=d/2 — note I uses /64, unlike the polar moment J=πd⁴/32 used for torsion."},
{title:"Beam deflection formulas",body:"For a cantilever with a point load P at the free end, δ_max=PL³/(3EI) at the free end. For a simply supported beam with a center point load P, δ_max=PL³/(48EI) at midspan. For loads elsewhere, superpose the effects of each load using standard formulas from a reference table."}
];

const flashcardsBeams=[
{front:"Shear-load relationship",back:"dV/dx=−w(x)",note:"The slope of the shear diagram equals negative the distributed load intensity."},
{front:"Moment-shear relationship",back:"dM/dx=V(x)",note:"Maximum moment occurs where V=0 (slope of M is zero there)."},
{front:"Flexure (bending) stress",back:"σ=Mc/I",note:"c is from the neutral axis to the extreme fiber; tension and compression occur on opposite faces."},
{front:"Rectangular section I",back:"I=bh³/12",note:"h is the depth (dimension parallel to the bending direction), not the width."},
{front:"Circular section I",back:"I=πd⁴/64",note:"Half of the polar moment J=πd⁴/32 — don't mix the two up."},
{front:"Section modulus",back:"S=I/c=bh²/6 for a rectangle",note:"σ_max=M/S — handy when c and I are always used together."},
{front:"Cantilever, end point load",back:"δ_max=PL³/(3EI) at the free end",note:"Maximum moment for this case is at the fixed support, M=PL."},
{front:"Simply supported, center point load",back:"δ_max=PL³/(48EI) at midspan",note:"Maximum moment is at midspan, M=PL/4."}
];

const questionsBeams:Question[]=[
{id:"MOM03-Q01",skill:"Shear diagrams",difficulty:"Easy",prompt:"A simply supported beam, 6 m long, carries a single point load of 12 kN at midspan. Find the maximum shear force in the beam.",choices:["3 kN","6 kN","12 kN","24 kN"],answer:1,explanation:"The maximum shear force is 6 kN.",solution:"Step 1 — By symmetry, each support reaction equals half the total load: R=P/2=12/2.\nStep 2 — R=6 kN.\nStep 3 — The shear force equals the reaction until the load point is reached.\nFinal answer: 6 kN.",trap:"12 kN uses the full applied load as the shear force, forgetting that the load splits evenly between the two supports.",repair:"For a symmetric simply supported beam, each reaction equals half the total load; shear equals the reaction magnitude between the support and the next load."},
{id:"MOM03-Q02",skill:"Moment diagrams",difficulty:"Easy",prompt:"For the same beam (6 m span, 12 kN point load at midspan), find the maximum bending moment.",choices:["9 kN·m","18 kN·m","36 kN·m","72 kN·m"],answer:1,explanation:"The maximum bending moment is 18 kN·m.",solution:"Step 1 — For a center point load, M_max=PL/4.\nStep 2 — M_max=(12)(6)/4.\nFinal answer: 18 kN·m.",trap:"36 kN·m comes from using PL/2 instead of PL/4, mixing up the moment formula with the reaction formula.",repair:"For a center point load on a simply supported beam, M_max=PL/4 — verify with M=R×(L/2)=(P/2)(L/2)=PL/4."},
{id:"MOM03-Q03",skill:"Flexure formula",difficulty:"Medium",prompt:"A rectangular beam cross-section, 100 mm wide and 200 mm deep, resists a bending moment of 40 kN·m. Find the maximum bending stress.",choices:["30.0 MPa","60.0 MPa","120.0 MPa","240.0 MPa"],answer:1,explanation:"The maximum bending stress is 60.0 MPa.",solution:"Step 1 — I=bh³/12=(100)(200)³/12=66,666,667 mm⁴.\nStep 2 — c=h/2=100 mm.\nStep 3 — σ=Mc/I=(40,000,000 N·mm)(100 mm)/66,666,667 mm⁴.\nFinal answer: 60.0 MPa.",trap:"120.0 MPa comes from using c=200 mm (the full depth) instead of c=100 mm (half the depth) in σ=Mc/I, doubling the computed stress.",repair:"c in σ=Mc/I is the distance from the neutral axis to the extreme fiber — half the total depth for a symmetric rectangular section, not the full depth."},
{id:"MOM03-Q04",skill:"Flexure formula, circular section",difficulty:"Medium",prompt:"A solid circular beam, 80 mm in diameter, resists a bending moment of 5 kN·m. Find the maximum bending stress.",choices:["49.7 MPa","99.5 MPa","198.9 MPa","397.9 MPa"],answer:1,explanation:"The maximum bending stress is about 99.5 MPa.",solution:"Step 1 — I=πd⁴/64=π(80)⁴/64=2,010,619 mm⁴.\nStep 2 — c=d/2=40 mm.\nStep 3 — σ=Mc/I=(5,000,000 N·mm)(40 mm)/2,010,619 mm⁴.\nFinal answer: 99.5 MPa.",trap:"49.7 MPa comes from using the polar moment of inertia J=πd⁴/32 in place of the bending moment of inertia I=πd⁴/64, understating the stress by half.",repair:"For bending stress use I=πd⁴/64 about the neutral axis; reserve J=πd⁴/32 for torsion about the shaft's longitudinal axis."},
{id:"MOM03-Q05",skill:"Cantilever deflection",difficulty:"Medium",prompt:"A cantilever steel beam (E=200 GPa), 2 m long with a rectangular cross-section 50 mm wide by 100 mm deep, carries a 5 kN point load at the free end. Find the maximum deflection.",choices:["4.0 mm","16.0 mm","32.0 mm","48.0 mm"],answer:1,explanation:"The maximum deflection is about 16.0 mm.",solution:"Step 1 — I=bh³/12=(50)(100)³/12=4,166,667 mm⁴.\nStep 2 — δ_max=PL³/(3EI), with P=5000 N, L=2000 mm.\nStep 3 — δ_max=(5000)(2000)³/(3×200,000×4,166,667)=4.0×10¹³/2.5×10¹².\nFinal answer: 16.0 mm.",trap:"48.0 mm results from forgetting the factor of 3 in the denominator of δ=PL³/(3EI), effectively computing PL³/(EI).",repair:"Memorize the cantilever end-load deflection formula exactly as δ=PL³/(3EI) — the 3 in the denominator is not optional."},
{id:"MOM03-Q06",skill:"Simply supported deflection",difficulty:"Medium",prompt:"A simply supported beam, 4 m span, with I=20×10⁶ mm⁴ and E=200 GPa, carries a 10 kN point load at midspan. Find the maximum deflection.",choices:["1.67 mm","3.33 mm","6.67 mm","10.0 mm"],answer:1,explanation:"The maximum deflection is about 3.33 mm.",solution:"Step 1 — δ_max=PL³/(48EI), with P=10,000 N, L=4000 mm.\nStep 2 — δ_max=(10,000)(4000)³/(48×200,000×20,000,000).\nStep 3 — Numerator=6.4×10¹⁴; Denominator=1.92×10¹⁴.\nFinal answer: 3.33 mm.",trap:"6.67 mm comes from using 24 instead of 48 in the denominator (δ=PL³/(24EI)), a common mix-up with other standard beam-deflection coefficients.",repair:"Double-check the deflection coefficient against a reference table — a center point load on a simply supported beam uses exactly 48 in the denominator."},
{id:"MOM03-Q07",skill:"Reactions and moment for an off-center load",difficulty:"Hard",prompt:"A simply supported beam, 10 m long, carries a single point load of 20 kN located 4 m from the left support A (6 m from the right support B). Find the maximum bending moment in the beam.",choices:["32 kN·m","48 kN·m","60 kN·m","80 kN·m"],answer:1,explanation:"The maximum bending moment is 48 kN·m.",solution:"Step 1 — Sum moments about A to find R_B: R_B(10)=20(4), so R_B=8 kN.\nStep 2 — R_A=20−8=12 kN.\nStep 3 — Maximum moment occurs under the load: M_max=R_A×a=12×4.\nFinal answer: 48 kN·m (check: R_B×b=8×6=48 kN·m, consistent).",trap:"32 kN·m comes from swapping the reactions (using R_A=8 kN and R_B=12 kN instead of the correct R_A=12 kN, R_B=8 kN).",repair:"The reaction closer to the load carries the larger share — verify by confirming R_A+R_B equals the total applied load and that the moments about each support balance."},
{id:"MOM03-Q08",skill:"Combined UDL and point load moment",difficulty:"Hard",prompt:"A cantilever beam, 3 m long, fixed at the left end, carries a uniformly distributed load of 6 kN/m over its entire length plus a concentrated 8 kN point load at the free end. Find the maximum bending moment (at the fixed support).",choices:["24 kN·m","27 kN·m","51 kN·m","78 kN·m"],answer:2,explanation:"The maximum bending moment at the fixed support is 51 kN·m.",solution:"Step 1 — Moment from the point load: M1=PL=8×3=24 kN·m.\nStep 2 — Moment from the distributed load: M2=wL²/2=6(3)²/2=27 kN·m.\nStep 3 — Superpose the two: M_max=M1+M2=24+27.\nFinal answer: 51 kN·m.",trap:"27 kN·m accounts only for the distributed load's moment (wL²/2) and omits the 24 kN·m contribution from the point load at the free end.",repair:"For combined loading, superpose the moment contributions of every load acting on the beam — sum each load's individual moment about the critical section."},
{id:"MOM03-Q09",skill:"Shear-moment relationship concepts",difficulty:"Easy",prompt:"On a beam's shear diagram, the location of the maximum bending moment occurs where:",choices:["the shear diagram crosses zero (V=0)","the shear diagram is at its maximum value","the distributed load is maximum","the beam has its minimum cross-sectional area"],answer:0,explanation:"Maximum moment occurs where V=0, since dM/dx=V.",solution:"Step 1 — dM/dx=V(x), so the moment diagram's slope equals the shear value.\nStep 2 — At a local extreme of M, the slope of M must be zero.\nStep 3 — Therefore V=0 at that location.\nFinal answer: the shear diagram crosses zero (V=0).",trap:"Choosing 'the shear diagram is at its maximum value' confuses the peak of V with the peak of M — those occur at different locations except in special cases.",repair:"Remember dM/dx=V: set V=0 and solve for x to locate candidate points of maximum moment, rather than looking for the peak of the V diagram."},
{id:"MOM03-Q10",skill:"Section modulus and stress",difficulty:"Medium",prompt:"A rectangular beam cross-section, 80 mm wide and 160 mm deep, resists a bending moment of 12 kN·m. Using the section modulus S=bh²/6, find the maximum bending stress.",choices:["17.6 MPa","35.2 MPa","70.3 MPa","140.6 MPa"],answer:1,explanation:"The maximum bending stress is about 35.2 MPa.",solution:"Step 1 — S=bh²/6=(80)(160)²/6=341,333 mm³.\nStep 2 — σ=M/S=(12,000,000 N·mm)/341,333 mm³.\nFinal answer: 35.2 MPa.",trap:"70.3 MPa comes from computing the section modulus as S=bh²/3 instead of the correct S=bh²/6, halving S and doubling the resulting stress.",repair:"Derive S from S=I/c=(bh³/12)/(h/2)=bh²/6 rather than recalling the coefficient from memory alone — rederive it if unsure."}
];

export const mechanicsBeamsModule:StudyModule={id:"MOM-03",subjectId:"mechanics-materials",sectionId:"beams",title:"Beams: Shear, Moment, and Deflection",lessons:lessonsBeams,flashcards:flashcardsBeams,questions:questionsBeams};

// ---------- MOM-04: Combined Loading and Stress Transformation ----------

const lessonsCombinedLoading=[
{title:"Combined axial and bending stress",body:"When a member carries both an axial force and a bending moment, superpose the stresses: σ=P/A ± Mc/I. On the fiber where axial and bending stresses have the same sign, they add; on the opposite fiber, they subtract. Always assign a sign convention and combine fiber-by-fiber."},
{title:"Plane stress transformation",body:"Given stresses σx, σy, and τxy on the original x-y axes, the transformation equations give the normal and shear stress on any plane rotated by θ: σx'=(σx+σy)/2+(σx−σy)/2·cos2θ+τxy·sin2θ, and τx'y'=−(σx−σy)/2·sin2θ+τxy·cos2θ."},
{title:"Principal stresses",body:"The principal stresses are the maximum and minimum normal stresses at a point, occurring on planes where the shear stress is zero: σ1,2=(σx+σy)/2 ± √[((σx−σy)/2)²+τxy²]. The principal angle satisfies tan2θp=2τxy/(σx−σy) — solve for 2θp first, then divide by 2."},
{title:"Maximum in-plane shear stress",body:"The maximum in-plane shear stress is τmax=√[((σx−σy)/2)²+τxy²], the same square-root term (the Mohr's-circle radius) used for the principal stresses. It occurs on planes 45° from the principal planes, where the normal stress equals the average, (σx+σy)/2."}
];

const flashcardsCombinedLoading=[
{front:"Combined axial + bending stress",back:"σ=P/A ± Mc/I",note:"Add where both are tensile (or both compressive) on the same fiber; subtract on the opposite fiber."},
{front:"Normal stress transformation",back:"σx'=(σx+σy)/2+(σx−σy)/2·cos2θ+τxy·sin2θ",note:"θ is measured counterclockwise from the original x-axis."},
{front:"Shear stress transformation",back:"τx'y'=−(σx−σy)/2·sin2θ+τxy·cos2θ",note:"Zero shear occurs on the principal planes."},
{front:"Principal stresses",back:"σ1,2=(σx+σy)/2 ± √[((σx−σy)/2)²+τxy²]",note:"σ1 is the larger (max) principal stress, σ2 the smaller (min)."},
{front:"Maximum in-plane shear stress",back:"τmax=√[((σx−σy)/2)²+τxy²]",note:"Occurs 45° from the principal planes; equals the radius of Mohr's circle."},
{front:"Average normal stress",back:"σavg=(σx+σy)/2",note:"This is the center of Mohr's circle, and acts on the max-shear planes."},
{front:"Principal angle",back:"tan2θp=2τxy/(σx−σy)",note:"Solve for 2θp first, then divide by 2 to get θp."},
{front:"Mohr's circle radius",back:"R=√[((σx−σy)/2)²+τxy²]=τmax",note:"Center is at (σavg,0); principal stresses are center ± R."}
];

const questionsCombinedLoading:Question[]=[
{id:"MOM04-Q01",skill:"Combined axial and bending stress",difficulty:"Medium",prompt:"A rectangular bar, 40 mm wide and 100 mm deep, carries an axial tensile force of 60 kN and a bending moment of 3 kN·m that produces tension on the same face as the axial load. Find the maximum normal stress on that face.",choices:["30 MPa","45 MPa","60 MPa","75 MPa"],answer:2,explanation:"The maximum normal stress is 60 MPa.",solution:"Step 1 — Axial stress: σ_axial=P/A=60,000/(40×100)=15 MPa.\nStep 2 — I=bh³/12=(40)(100)³/12=3,333,333 mm⁴; c=50 mm.\nStep 3 — Bending stress: σ_bend=Mc/I=(3,000,000)(50)/3,333,333=45 MPa.\nStep 4 — Combine (same sign on this face): σ_total=σ_axial+σ_bend=15+45.\nFinal answer: 60 MPa.",trap:"45 MPa reports only the bending stress and forgets to add the 15 MPa axial stress.",repair:"Combined loading requires adding the axial stress AND the bending stress at the fiber of interest — don't report just one term."},
{id:"MOM04-Q02",skill:"Combined loading concepts",difficulty:"Easy",prompt:"A cantilever beam also carries an axial tensile force. If the bending moment causes tension on the top fiber, on which fiber does the bending stress ADD to the axial tensile stress?",choices:["Top fiber only","Bottom fiber only","Both fibers equally","Neither fiber"],answer:0,explanation:"Bending tension adds to axial tension only on the top fiber.",solution:"Step 1 — Axial tension produces uniform tensile stress on every fiber.\nStep 2 — Bending produces tension on top and compression on bottom (as given).\nStep 3 — On the top fiber, axial tension (+) and bending tension (+) have the same sign, so they add.\nStep 4 — On the bottom fiber, axial tension (+) and bending compression (−) have opposite signs, so they subtract.\nFinal answer: Top fiber only.",trap:"Choosing 'Both fibers equally' ignores that bending stress reverses sign between the top and bottom fibers, while axial stress does not.",repair:"Assign a sign convention (tension positive) to both the axial and bending stress separately, then add them fiber-by-fiber — don't assume they combine the same way on every face."},
{id:"MOM04-Q03",skill:"Principal stresses",difficulty:"Medium",prompt:"At a point, σx=80 MPa, σy=20 MPa, and τxy=30 MPa. Find the maximum principal stress.",choices:["50.0 MPa","57.6 MPa","92.4 MPa","117.1 MPa"],answer:2,explanation:"The maximum principal stress is about 92.4 MPa.",solution:"Step 1 — Average stress: σavg=(80+20)/2=50 MPa.\nStep 2 — Half-difference: (σx−σy)/2=(80−20)/2=30 MPa.\nStep 3 — R=√(30²+30²)=√1800=42.4 MPa.\nStep 4 — σ1=σavg+R=50+42.4.\nFinal answer: 92.4 MPa.",trap:"117.1 MPa comes from using the full difference (σx−σy)=60 inside the square root instead of half the difference (σx−σy)/2=30, inflating the radius R and thus σ1.",repair:"The Mohr's-circle radius uses HALF the stress difference: R=√[((σx−σy)/2)²+τxy²] — don't forget to divide by 2 before squaring."},
{id:"MOM04-Q04",skill:"Maximum in-plane shear stress",difficulty:"Medium",prompt:"At a point, σx=60 MPa, σy=−20 MPa, and τxy=40 MPa. Find the maximum in-plane shear stress.",choices:["28.3 MPa","40.0 MPa","56.6 MPa","80.0 MPa"],answer:2,explanation:"The maximum in-plane shear stress is about 56.6 MPa.",solution:"Step 1 — Half-difference: (σx−σy)/2=(60−(−20))/2=40 MPa.\nStep 2 — τmax=√[((σx−σy)/2)²+τxy²]=√(40²+40²).\nStep 3 — τmax=√3200.\nFinal answer: 56.6 MPa.",trap:"40.0 MPa reports only (σx−σy)/2 and ignores the τxy contribution entirely, as if τmax were just the half-difference term.",repair:"τmax combines BOTH the normal stress difference and the applied shear via the Pythagorean sum — it isn't just (σx−σy)/2 unless τxy=0."},
{id:"MOM04-Q05",skill:"Combined axial and torsional loading",difficulty:"Hard",prompt:"A solid circular shaft, 50 mm in diameter, carries a simultaneous axial tensile force of 40 kN and a torque of 600 N·m. Find the maximum in-plane shear stress at the outer surface (σy=0).",choices:["10.2 MPa","20.4 MPa","24.4 MPa","26.5 MPa"],answer:3,explanation:"The maximum in-plane shear stress is about 26.5 MPa.",solution:"Step 1 — Axial stress: σx=P/A=40,000/[(π/4)(50)²]=40,000/1963.5=20.4 MPa; σy=0.\nStep 2 — Torsional shear: J=πd⁴/32=613,592 mm⁴, τxy=Tc/J=(600,000)(25)/613,592=24.4 MPa.\nStep 3 — Half-difference: σx/2=10.2 MPa.\nStep 4 — τmax=√(10.2²+24.4²)=√701.4.\nFinal answer: 26.5 MPa.",trap:"24.4 MPa is just the torsional shear stress τxy alone — it ignores that the axial stress σx also increases the maximum in-plane shear via τmax=√[(σx/2)²+τxy²] (since σy=0).",repair:"When axial and torsional loads act together, combine BOTH stress components through the full τmax formula — don't report the torsional shear alone as the answer."},
{id:"MOM04-Q06",skill:"Stress transformation",difficulty:"Medium",prompt:"At a point, σx=100 MPa, σy=40 MPa, and τxy=0. Find the normal stress on a plane rotated 30° from the x-axis.",choices:["55 MPa","70 MPa","85 MPa","100 MPa"],answer:2,explanation:"The normal stress on the rotated plane is 85 MPa.",solution:"Step 1 — σx'=(σx+σy)/2+(σx−σy)/2·cos2θ+τxy·sin2θ.\nStep 2 — (σx+σy)/2=70 MPa; (σx−σy)/2=30 MPa; 2θ=60°.\nStep 3 — σx'=70+30·cos60°+0=70+30(0.5).\nFinal answer: 85 MPa.",trap:"70 MPa reports only the average stress term and drops the cos2θ term entirely, as if the orientation θ had no effect.",repair:"The transformation equation has multiple terms — average, plus the cos2θ term, plus the shear sin2θ term; don't drop the orientation-dependent terms."},
{id:"MOM04-Q07",skill:"Shear stress transformation",difficulty:"Hard",prompt:"At a point, σx=90 MPa, σy=30 MPa, and τxy=20 MPa. Find the shear stress on a plane rotated 25° from the x-axis.",choices:["−10.1 MPa","−4.5 MPa","10.1 MPa","22.8 MPa"],answer:0,explanation:"The shear stress on the rotated plane is about −10.1 MPa.",solution:"Step 1 — τx'y'=−(σx−σy)/2·sin2θ+τxy·cos2θ.\nStep 2 — (σx−σy)/2=30 MPa; 2θ=50°.\nStep 3 — −30·sin50°=−30(0.7660)=−22.98 MPa.\nStep 4 — 20·cos50°=20(0.6428)=12.86 MPa.\nStep 5 — τx'y'=−22.98+12.86.\nFinal answer: −10.1 MPa.",trap:"22.8 MPa comes from computing only the −(σx−σy)/2·sin2θ term and forgetting to add the τxy·cos2θ contribution (and dropping the negative sign).",repair:"Compute both terms of the shear transformation equation separately, keep track of signs throughout, and add them — don't stop after the first term."},
{id:"MOM04-Q08",skill:"Principal angle",difficulty:"Hard",prompt:"At a point, σx=50 MPa, σy=−10 MPa, and τxy=25 MPa. Find the principal angle θp (between 0° and 90°).",choices:["9.95°","19.9°","39.8°","45.0°"],answer:1,explanation:"The principal angle is about 19.9°.",solution:"Step 1 — tan2θp=2τxy/(σx−σy)=2(25)/(50−(−10))=50/60=0.8333.\nStep 2 — 2θp=tan⁻¹(0.8333)≈39.8°.\nStep 3 — Divide by 2 to get θp.\nFinal answer: 19.9°.",trap:"39.8° comes from forgetting to divide by 2 at the end, reporting 2θp itself as the principal angle instead of θp.",repair:"Solve for 2θp first using the arctan, then divide by 2 to get the actual principal-plane angle θp — don't report 2θp as the final answer."},
{id:"MOM04-Q09",skill:"Principal plane concepts",difficulty:"Easy",prompt:"On the principal planes of a stressed element, the shear stress is:",choices:["Zero","Maximum","Equal to the average normal stress","Equal to τxy"],answer:0,explanation:"Principal planes are, by definition, planes of zero shear stress.",solution:"Step 1 — Principal stresses are defined as the extreme (max/min) normal stresses on an element.\nStep 2 — At a normal-stress extreme, the transformation equation's slope with respect to θ is zero, which corresponds to τx'y'=0.\nStep 3 — Therefore the principal planes are, by definition, planes of zero shear stress.\nFinal answer: Zero.",trap:"Choosing 'Maximum' confuses principal planes (zero shear) with the max-shear planes, which are rotated 45° away from the principal planes.",repair:"Keep principal planes (zero shear, extreme normal stress) and max-shear planes (extreme shear, 45° away) as two distinct, related-but-different concepts."},
{id:"MOM04-Q10",skill:"Combined stress design check",difficulty:"Medium",prompt:"A steel bracket cross-section (area 1500 mm², I=800×10³ mm⁴, c=25 mm) carries an axial compressive force of 30 kN and a bending moment of 1.8 kN·m that produces compressive stress on the same fiber as the axial load. If the allowable compressive stress is 90 MPa, what is the actual maximum compressive stress on that fiber?",choices:["56.3 MPa","76.3 MPa","96.3 MPa","106.3 MPa"],answer:1,explanation:"The maximum compressive stress is about 76.3 MPa, which is within the 90 MPa allowable.",solution:"Step 1 — Axial stress: σ_axial=P/A=30,000/1500=20 MPa.\nStep 2 — Bending stress: σ_bend=Mc/I=(1,800,000)(25)/800,000=56.25 MPa.\nStep 3 — Combine (same sign on this fiber): σ_total=20+56.25.\nFinal answer: 76.3 MPa (safe, below the 90 MPa allowable).",trap:"56.3 MPa is just the bending stress term (Mc/I); it omits the 20 MPa axial contribution, understating the true combined stress.",repair:"Always compute and sum BOTH the axial term (P/A) and the bending term (Mc/I) at the fiber of interest before comparing to the allowable stress."}
];

export const mechanicsCombinedLoadingModule:StudyModule={id:"MOM-04",subjectId:"mechanics-materials",sectionId:"combined-loading",title:"Combined Loading and Stress Transformation",lessons:lessonsCombinedLoading,flashcards:flashcardsCombinedLoading,questions:questionsCombinedLoading};

// ---------- MOM-05: Columns and Stability ----------

const lessonsColumns=[
{title:"Euler buckling load",body:"For a slender column, the critical elastic buckling load is Pcr=π²EI/(KL)², where I is the MINIMUM moment of inertia of the cross-section (buckling occurs about the weak axis) and KL is the effective length. Increasing KL sharply reduces Pcr, since it is squared in the denominator."},
{title:"Effective length factor K",body:"K depends on the end conditions: pinned-pinned K=1.0, fixed-fixed K=0.5, fixed-pinned K≈0.7, and fixed-free (like a flagpole) K=2.0. Using the wrong K for the stated end conditions is one of the most common Euler-buckling mistakes."},
{title:"Slenderness ratio and radius of gyration",body:"The slenderness ratio is λ=KL/r, where r=√(I/A) is the radius of gyration. Use I_min to get the governing (minimum) r, since the column buckles about its weakest axis first. Euler's formula is valid only for long, slender columns; short columns yield or crush instead."},
{title:"Critical buckling stress",body:"The critical stress is σcr=Pcr/A=π²E/(KL/r)²=π²E/λ². Compare σcr to the material's yield strength: if the computed σcr exceeds yield, the column yields before it can buckle elastically, and Euler's formula no longer governs the design."}
];

const flashcardsColumns=[
{front:"Euler critical load",back:"Pcr=π²EI/(KL)²",note:"I is the MINIMUM moment of inertia — buckling occurs about the weak axis."},
{front:"K for pinned-pinned",back:"K=1.0",note:"The baseline/default case."},
{front:"K for fixed-fixed",back:"K=0.5",note:"Both ends restrained against rotation — stiffest case, highest Pcr."},
{front:"K for fixed-free",back:"K=2.0",note:"Like a flagpole — weakest case, lowest Pcr."},
{front:"K for fixed-pinned",back:"K≈0.7",note:"One end fixed, one end pinned."},
{front:"Radius of gyration",back:"r=√(I/A)",note:"Use the minimum I (weak-axis) to get the governing (minimum) r."},
{front:"Slenderness ratio",back:"λ=KL/r",note:"Higher λ means more slender, and a lower critical stress."},
{front:"Critical (Euler) stress",back:"σcr=π²E/(KL/r)²",note:"Valid only while σcr stays below the material's yield strength."}
];

const questionsColumns:Question[]=[
{id:"MOM05-Q01",skill:"Euler buckling load",difficulty:"Medium",prompt:"A pinned-pinned steel column (E=200 GPa), 3 m long, has I=8×10⁶ mm⁴. Find the critical Euler buckling load.",choices:["438.6 kN","877.3 kN","1754.6 kN","3509.2 kN"],answer:2,explanation:"The critical buckling load is about 1754.6 kN.",solution:"Step 1 — Pinned-pinned: K=1.0, so KL=3000 mm.\nStep 2 — Pcr=π²EI/(KL)²=π²(200,000)(8,000,000)/(3000)².\nStep 3 — Numerator=π²×1.6×10¹²=1.579×10¹³; Denominator=9,000,000.\nFinal answer: 1754.6 kN.",trap:"438.6 kN results from using K=2.0 (fixed-free) instead of the correct K=1.0 for pinned-pinned end conditions, quadrupling (KL)² and cutting Pcr to one-fourth.",repair:"Match K to the actual end conditions stated in the problem — pinned-pinned is K=1.0, not the fixed-free flagpole case (K=2.0)."},
{id:"MOM05-Q02",skill:"End condition concepts",difficulty:"Easy",prompt:"Which end condition gives the HIGHEST Euler critical buckling load for a column of given length, E, and I?",choices:["Pinned-pinned (K=1.0)","Fixed-free (K=2.0)","Fixed-pinned (K=0.7)","Fixed-fixed (K=0.5)"],answer:3,explanation:"Fixed-fixed has the smallest K, giving the highest Pcr.",solution:"Step 1 — Pcr=π²EI/(KL)² is inversely proportional to K².\nStep 2 — A smaller K gives a larger Pcr for the same E, I, and L.\nStep 3 — Among the four listed cases, K=0.5 (fixed-fixed) is the smallest.\nFinal answer: Fixed-fixed (K=0.5).",trap:"Choosing 'Pinned-pinned (K=1.0)' treats it as the default/strongest case, but fixed-fixed restrains rotation at both ends, giving an even smaller effective length and a higher Pcr.",repair:"Rank end conditions by K value directly — the smallest K always gives the largest Euler buckling load."},
{id:"MOM05-Q03",skill:"Radius of gyration",difficulty:"Medium",prompt:"A column has a rectangular cross-section, 40 mm by 80 mm. Find the minimum radius of gyration (the value that governs buckling).",choices:["5.77 mm","11.55 mm","23.09 mm","33.33 mm"],answer:1,explanation:"The minimum radius of gyration is about 11.55 mm.",solution:"Step 1 — The minimum I uses the smaller dimension cubed: I_min=(80)(40)³/12=426,667 mm⁴.\nStep 2 — A=40×80=3200 mm².\nStep 3 — r_min=√(I_min/A)=√(426,667/3200)=√133.3.\nFinal answer: 11.55 mm.",trap:"23.09 mm comes from using the LARGER moment of inertia (about the strong axis, I_max=(40)(80)³/12) instead of the minimum I about the weak axis.",repair:"For an unsymmetric cross-section, always use I_min (and thus r_min) when checking column buckling — the column buckles about its weakest axis first."},
{id:"MOM05-Q04",skill:"Slenderness ratio",difficulty:"Medium",prompt:"For the same column (rectangular cross-section 40 mm by 80 mm, r_min=11.55 mm), with a pinned-pinned length of 2.5 m, find the governing slenderness ratio.",choices:["54.1","108.3","162.4","216.5"],answer:3,explanation:"The governing slenderness ratio is about 216.5.",solution:"Step 1 — λ=KL/r, with K=1.0, L=2500 mm.\nStep 2 — λ=2500/11.55.\nFinal answer: 216.5.",trap:"108.3 comes from using r_max (about the strong axis, 23.09 mm) instead of r_min about the weak axis, understating the true (governing) slenderness ratio by half.",repair:"Always use r_min (from I_min) to compute the governing slenderness ratio — the column buckles about its weakest axis."},
{id:"MOM05-Q05",skill:"Critical buckling stress",difficulty:"Medium",prompt:"A pinned-pinned column has a slenderness ratio λ=120 and is made of steel (E=200 GPa). Find the Euler critical stress.",choices:["68.5 MPa","137.1 MPa","274.2 MPa","548.3 MPa"],answer:1,explanation:"The Euler critical stress is about 137.1 MPa.",solution:"Step 1 — σcr=π²E/λ².\nStep 2 — σcr=π²(200,000)/(120)²=1,973,920/14,400.\nFinal answer: 137.1 MPa.",trap:"548.3 MPa comes from using half the slenderness ratio (λ=60 instead of 120); since σcr∝1/λ², halving λ quadruples the computed critical stress.",repair:"Double-check the slenderness ratio value carried forward from earlier calculations before squaring it in the denominator — errors there get amplified by the square."},
{id:"MOM05-Q06",skill:"Factor of safety against buckling",difficulty:"Hard",prompt:"A pin-connected aluminum column (E=70 GPa) has a solid circular cross-section, 30 mm in diameter, and is 1.8 m long. It supports an axial compressive load of 3 kN. Find the factor of safety against Euler buckling.",choices:["0.57","1.41","2.83","5.65"],answer:2,explanation:"The factor of safety against buckling is about 2.83.",solution:"Step 1 — I=πd⁴/64=π(30)⁴/64=39,761 mm⁴.\nStep 2 — Pcr=π²EI/(KL)²=π²(70,000)(39,761)/(1800)²=8478 N.\nStep 3 — FS=Pcr/P_applied=8478/3000.\nFinal answer: 2.83.",trap:"5.65 comes from using J=πd⁴/32 (the polar moment for torsion) instead of the correct I=πd⁴/64 (the area moment of inertia for bending/buckling), doubling the computed Pcr and thus the factor of safety.",repair:"Column buckling uses the bending moment of inertia I=πd⁴/64 about a diameter — the same I used for beam flexure, not the polar moment J used for torsion."},
{id:"MOM05-Q07",skill:"Euler formula applicability",difficulty:"Easy",prompt:"Euler's buckling formula is valid only for columns that are:",choices:["Short and stocky","Long and slender","Made of brittle material only","Loaded eccentrically"],answer:1,explanation:"Euler's formula applies to long, slender columns that buckle elastically before yielding.",solution:"Step 1 — Euler buckling assumes the column remains elastic up to the point of buckling.\nStep 2 — Short, stocky columns reach the material's yield stress before the computed Euler stress is reached, so they fail by yielding or crushing, not elastic buckling.\nStep 3 — Only long, slender columns (high slenderness ratio) buckle elastically at a stress below yield, where Euler's formula is valid.\nFinal answer: Long and slender.",trap:"Choosing 'Short and stocky' reverses the applicability — short columns are governed by yield/crushing strength (or empirical intermediate-column formulas), not the Euler formula.",repair:"Before applying Euler's formula, check that the computed critical stress is below the material's yield strength — if not, the column is too short/stocky for Euler buckling to govern."},
{id:"MOM05-Q08",skill:"Effective length",difficulty:"Medium",prompt:"A column is fixed at the base and free at the top (like a flagpole), with an actual length of 4 m. What is its effective length KL?",choices:["2.0 m","2.8 m","4.0 m","8.0 m"],answer:3,explanation:"The effective length is 8.0 m.",solution:"Step 1 — Fixed-free (flagpole) condition: K=2.0.\nStep 2 — KL=2.0×4.\nFinal answer: 8.0 m.",trap:"2.8 m comes from using K=0.7 (the fixed-pinned effective length factor) instead of K=2.0 for the fixed-free (flagpole) condition described.",repair:"Match the K factor to the exact end conditions: a truly fixed-free 'flagpole' column is K=2.0, not fixed-pinned's K=0.7."},
{id:"MOM05-Q09",skill:"Column design for a target factor of safety",difficulty:"Hard",prompt:"A pinned-pinned solid circular steel column (E=200 GPa) is 2.4 m long and must support an axial load of 100 kN with a factor of safety of 3 against Euler buckling. What is the minimum required diameter?",choices:["41.0 mm","49.4 mm","65.0 mm","81.9 mm"],answer:2,explanation:"The minimum required diameter is about 65.0 mm.",solution:"Step 1 — Required buckling load: Pcr=FS×P=3×100=300 kN.\nStep 2 — Solve Pcr=π²EI/(KL)² for I: I=Pcr(KL)²/(π²E)=(300,000)(2400)²/(π²×200,000)=875,387 mm⁴.\nStep 3 — Solve I=πd⁴/64 for d: d⁴=64I/π=17,832,900, so d=∜17,832,900.\nFinal answer: 65.0 mm.",trap:"49.4 mm comes from designing the column for the applied load alone (Pcr=100 kN) and forgetting to apply the required factor of safety of 3 to the target buckling load before solving for the diameter.",repair:"Apply the factor of safety to the required Pcr FIRST (Pcr_design=FS×P_applied), then solve for the section size — don't add the FS as an afterthought at the end."},
{id:"MOM05-Q10",skill:"Euler formula sensitivity",difficulty:"Easy",prompt:"For a column with a fixed slenderness ratio, doubling the modulus of elasticity E (holding geometry and end conditions fixed) has what effect on the Euler critical load Pcr?",choices:["Pcr is unchanged","Pcr doubles","Pcr is halved","Pcr increases by a factor of 4"],answer:1,explanation:"Pcr is directly proportional to E, so doubling E doubles Pcr.",solution:"Step 1 — Pcr=π²EI/(KL)².\nStep 2 — E appears to the first power in the numerator.\nStep 3 — Doubling E, with I, K, and L unchanged, directly doubles Pcr.\nFinal answer: Pcr doubles.",trap:"Choosing 'Pcr increases by a factor of 4' confuses E's linear relationship with the squared relationship that the effective length KL has in the formula.",repair:"Check each variable's exponent in the formula individually — E is linear, but the effective length KL is squared (and in the denominator)."}
];

